import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"Budget Reservation","description":"Why \\"check budget then pay\\" fails under concurrency, and how AgentPay prevents overspending with atomic reservation.","frontmatter":{"title":"Budget Reservation","description":"Why \\"check budget then pay\\" fails under concurrency, and how AgentPay prevents overspending with atomic reservation."},"headers":[],"relativePath":"learn/04-agentpay-concepts/budget-reservation.md","filePath":"learn/04-agentpay-concepts/budget-reservation.md","lastUpdated":1792490239000}'),i={name:"learn/04-agentpay-concepts/budget-reservation.md"};function r(o,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="budget-reservation" tabindex="-1">Budget Reservation <a class="header-anchor" href="#budget-reservation" aria-label="Permalink to &quot;Budget Reservation&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental Project</p><p>AgentPay has not undergone an independent security audit. Do not use with production funds. All examples on this page are based on testnets and test tokens.</p></div><h2 id="in-a-nutshell" tabindex="-1">In a Nutshell <a class="header-anchor" href="#in-a-nutshell" aria-label="Permalink to &quot;In a Nutshell&quot;">​</a></h2><p><strong>Budget check and budget deduction must be executed as a single indivisible action.</strong> Checking first and paying later inevitably results in overspending under concurrent load. AgentPay adopts a three-phase pattern: &quot;Reserve first, pay second, commit or release third.&quot;</p><h2 id="a-concrete-scenario" tabindex="-1">A Concrete Scenario <a class="header-anchor" href="#a-concrete-scenario" aria-label="Permalink to &quot;A Concrete Scenario&quot;">​</a></h2><p>You allocate a 24-hour budget of 10 USDC to an agent. At a certain moment, the agent concurrently dispatches two requests for 6 USDC each:</p><table tabindex="0"><thead><tr><th>Time</th><th>Request A</th><th>Request B</th></tr></thead><tbody><tr><td>t1</td><td>Reads remaining budget: 10</td><td>Reads remaining budget: 10</td></tr><tr><td>t2</td><td>10 ≥ 6, check passed</td><td>10 ≥ 6, check passed</td></tr><tr><td>t3</td><td>Pays 6 USDC</td><td>Pays 6 USDC</td></tr><tr><td>Outcome</td><td></td><td><strong>Total spent: 12 USDC, overspent by 2 USDC</strong></td></tr></tbody></table><p>Both requests were &quot;checked&quot;, but both decisions were based on the same stale balance. This is common in agent architectures: a single complex task routinely parallelizes multiple tool invocations, or multiple agents share a single collective budget.</p><p>The defect lies in the time window between t1 and t3: <strong>checking and deducting are decoupled.</strong></p><h2 id="common-approaches-and-why-they-fall-short" tabindex="-1">Common Approaches and Why They Fall Short <a class="header-anchor" href="#common-approaches-and-why-they-fall-short" aria-label="Permalink to &quot;Common Approaches and Why They Fall Short&quot;">​</a></h2><h3 id="approach-1-check-first-pay-later" tabindex="-1">Approach 1: Check First, Pay Later <a class="header-anchor" href="#approach-1-check-first-pay-later" aria-label="Permalink to &quot;Approach 1: Check First, Pay Later&quot;">​</a></h3><p>Described in the scenario above. The race window between check and payment allows concurrent requests to slip through simultaneously.</p><h3 id="approach-2-deduct-budget-only-after-successful-payment" tabindex="-1">Approach 2: Deduct Budget Only After Successful Payment <a class="header-anchor" href="#approach-2-deduct-budget-only-after-successful-payment" aria-label="Permalink to &quot;Approach 2: Deduct Budget Only After Successful Payment&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check → Make Payment → Deduct on Success</span></span></code></pre></div><p>The race window expands dramatically: it now spans the entire duration of network payment execution, during which all concurrent requests read an outdated balance.</p><h3 id="approach-3-in-memory-mutex-counter" tabindex="-1">Approach 3: In-Memory Mutex Counter <a class="header-anchor" href="#approach-3-in-memory-mutex-counter" aria-label="Permalink to &quot;Approach 3: In-Memory Mutex Counter&quot;">​</a></h3><p>An in-memory lock works for a single-threaded process, but agents commonly run across multiple processes or distributed containers, and processes restart. In-memory counters are neither shared nor persistent; restarting resets the available budget back to maximum.</p><h3 id="approach-4-deduct-immediately-on-request-never-refund-on-failure" tabindex="-1">Approach 4: Deduct Immediately on Request, Never Refund on Failure <a class="header-anchor" href="#approach-4-deduct-immediately-on-request-never-refund-on-failure" aria-label="Permalink to &quot;Approach 4: Deduct Immediately on Request, Never Refund on Failure&quot;">​</a></h3><p>This avoids overspending, but introduces another critical problem: when requests fail, get rejected upstream, or time out, budget remains permanently consumed. Over time, the budget &quot;leaks away&quot; until the agent is starved and incapacitated. Reserved funds must have a deterministic lifecycle.</p><h2 id="the-agentpay-approach-reserve-commit-release" tabindex="-1">The AgentPay Approach: Reserve, Commit, Release <a class="header-anchor" href="#the-agentpay-approach-reserve-commit-release" aria-label="Permalink to &quot;The AgentPay Approach: Reserve, Commit, Release&quot;">​</a></h2><p>AgentPay breaks the budget impact of a payment into three distinct lifecycle operations:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       Check Limit + Deduct Available      ← Single Atomic Operation</span></span>
<span class="line"><span>                     │</span></span>
<span class="line"><span>             Reserve Succeeded</span></span>
<span class="line"><span>                     │</span></span>
<span class="line"><span>    ┌────────────────┼────────────────┐</span></span>
<span class="line"><span>    ▼                ▼                ▼</span></span>
<span class="line"><span>Payment Success  Explicit Failure  Unknown Result</span></span>
<span class="line"><span>    │                │                │</span></span>
<span class="line"><span>  Commit          Release         Hold Active</span></span>
<span class="line"><span>(Accounted)   (Quota Restored) (Awaiting Reconciliation)</span></span></code></pre></div><p><strong>Step 1: Reserve.</strong> Check available quota and place a hold on that exact amount within a single atomic database transaction. No external request can observe an intermediate inconsistent state.</p><p><strong>Step 2: Pay.</strong> The signing and payment workflow begins only after reservation succeeds. If reservation fails, the request is rejected immediately without invoking the signer.</p><p><strong>Step 3: Commit or Release.</strong></p><ul><li>Payment confirmed successful → <strong>Commit</strong>: the reservation converts into an irrevocable debit.</li><li>Explicit failure (e.g., upstream 4xx client rejection) → <strong>Release</strong>: the hold is released and quota is restored.</li><li>Unknown result (e.g., network timeout) → <strong>Hold Active</strong>: reservation remains locked until reconciled, aligning strictly with <a href="./timeout-is-not-failure">Timeout Is Not Failure</a>.</li></ul><h3 id="returning-to-the-concurrency-scenario" tabindex="-1">Returning to the Concurrency Scenario <a class="header-anchor" href="#returning-to-the-concurrency-scenario" aria-label="Permalink to &quot;Returning to the Concurrency Scenario&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request A: Reserve 6 → Succeeded, remaining available: 4</span></span>
<span class="line"><span>Request B: Reserve 6 → Remaining 4 &lt; 6, rejected immediately</span></span></code></pre></div><p>Only one request passes; overspending is structurally impossible.</p><h3 id="how-atomicity-is-guaranteed" tabindex="-1">How Atomicity Is Guaranteed <a class="header-anchor" href="#how-atomicity-is-guaranteed" aria-label="Permalink to &quot;How Atomicity Is Guaranteed&quot;">​</a></h3><p>In AgentPay, reservation occurs at two architectural layers with equivalent semantics:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Purpose</th><th>Implementation</th></tr></thead><tbody><tr><td><strong>Buyer Local Firewall</strong></td><td>Restricts local agent spending</td><td>SQLite transaction with exclusive table locking before writes</td></tr><tr><td><strong>Gateway Platform Wallet</strong></td><td>Governs tenant virtual wallet debits</td><td>PostgreSQL row-level locks (<code>SELECT ... FOR UPDATE</code>), strictly queuing requests per wallet while keeping distinct wallets non-blocking</td></tr></tbody></table><p>On the platform wallet path, the core debit query uses conditional atomic updates:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ap_wallet</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available_cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available_cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :amount,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    held_cache      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> held_cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :amount</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> wallet_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :wallet_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available_cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :amount;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Affected rows = 0 implies insufficient balance; rejected immediately.</span></span></code></pre></div><p>Checking and deducting occur within a single SQL statement; the database guarantees isolation against concurrent transactions. In gateway concurrency test suites, 100 concurrent workers competing for a limited pool of funds consistently demonstrate that available balance never drops below zero.</p><h3 id="rolling-24-hour-budget-windows" tabindex="-1">Rolling 24-Hour Budget Windows <a class="header-anchor" href="#rolling-24-hour-budget-windows" aria-label="Permalink to &quot;Rolling 24-Hour Budget Windows&quot;">​</a></h3><p>AgentPay employs a <strong>sliding rolling window</strong> rather than calendar midnight resets:</p><ul><li>Fixed calendar window: Spending 10 USDC at 23:59 and another 10 USDC at 00:01 allows 20 USDC to be spent within two minutes.</li><li>Rolling window: At any given point in time $t$, total spend over the preceding interval $[t - 24\\text{h}, t]$ cannot exceed the ceiling.</li></ul><p>This eliminates calendar boundary arbitrage.</p><h3 id="reservation-ttl-and-expiration" tabindex="-1">Reservation TTL and Expiration <a class="header-anchor" href="#reservation-ttl-and-expiration" aria-label="Permalink to &quot;Reservation TTL and Expiration&quot;">​</a></h3><p>To prevent upstream hangs from permanently locking quota, holds carry a TTL (default: <code>upstream_timeout + 60s</code>). Expired reservations are processed by background recovery workers.</p><h2 id="configuration-guidelines" tabindex="-1">Configuration Guidelines <a class="header-anchor" href="#configuration-guidelines" aria-label="Permalink to &quot;Configuration Guidelines&quot;">​</a></h2><p><strong>One private key per ledger.</strong> Running multiple agent processes on the same private key with independent local SQLite ledgers gives each process a full budget replica, multiplying effective spend by the number of instances. The same wallet should share a centralized ledger; for multi-agent clusters, the Gateway platform wallet is the recommended model.</p><p><strong>Atomic integer amounts only.</strong> All numbers are stored and compared as integers in minimal token units (USDC uses 6 decimals). No floating-point rounding errors can accumulate.</p><p><strong>Fail-Closed on uncertainty.</strong> Transaction lock timeouts, deadlocks, and unexpected errors fail closed. It is always safer to decline a transaction than risk overspending.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><p><strong>Q: If a reservation is made but payment never happens, is quota locked forever?</strong><br> No. Explicit upstream rejections trigger immediate release. Uncertain outcomes remain held until timeout expiration, where background reconciliation safely unblocks the quota.</p><p><strong>Q: What happens when an agent exhausts its budget?</strong><br> Subsequent payments are immediately rejected with an explicit error code without generating signatures. You can adjust limits in the console or wait for older transactions to roll out of the 24-hour window.</p><p><strong>Q: Do row-level locks create bottlenecks under high concurrency?</strong><br> Requests on the same wallet serialize momentarily, but the transaction duration is minimal: select, update, insert audit event, and immediate commit—upstream network I/O is never executed while holding database locks. Distinct wallets execute completely in parallel.</p><p><strong>Q: Why separate single-transaction caps from 24-hour budgets?</strong><br> They address different threats: single-transaction caps prevent large unauthorized debits (e.g., prompt-injected price hikes), while budgets prevent runaway death spirals of many tiny micropayments.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Understand why uncertain timeouts require active holds: <a href="./timeout-is-not-failure">Timeout Is Not Failure</a></li><li>See policy interception in action: <a href="./../05-hands-on/policy-in-action">Policy in Action</a></li><li>Explore dual-rail wallet mechanics: <a href="./dual-rail">Dual-Rail Architecture</a></li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><ul><li><a href="/docs/specs/wallet-ledger">Wallet &amp; Ledger Specification</a>: Hold, capture, release, and reconciliation contracts</li><li><a href="/docs/specs/multitenant-data-model">Multitenant Data Model</a>: Database schema for wallets and reservations</li><li><a href="/docs/specs/threat-model-v1">Threat Model v1</a>: Double-spending and negative-balance mitigation</li><li><a href="/docs/specs/security-model">Security Model</a>: Concurrency budget competition and single-ledger rules</li></ul>`,54)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
